mapper.select:
SELECT COUNT(*) 
FROM WH_PRESS 
WHERE PRS_NAME = #{PRS_NAME} 
  AND PRS_COUNTRY = #{PRS_COUNTRY}

SELECT COUNT(*) FROM WH_PRESS A WHERE PRS_TYPE = '4' AND PRS_AUTH = 'ST'
AND PRS_COUNTRY = #{country}
AND (PRS_NAME LIKE CONCAT('%', #{searchKeyword}, '%') OR PRS_ID LIKE CONCAT('%', #{searchKeyword}, '%'))

mapper.update:
UPDATE WH_PRESS
SET IS_POPULAR = #{IS_POPULAR}
WHERE PRS_ID = #{PRS_ID}

mapper.select:
SELECT A.CON_ID, A.CON_BODY, A.CREATED_DATE, A.IS_PINNED, B.PRS_NAME, B.PRS_ID, D.THUMB_URL as image, D.MEDIA_URL, D.MEDIA_TYPE FROM WH_STAR_CONTENT A JOIN WH_PRESS B ON A.PRS_ID = B.PRS_ID JOIN STAR_CONTENT_MEDIA D ON A.CON_ID = D.CON_ID WHERE D.SORT_ORDER = 0
AND B.PRS_COUNTRY = #{country}
ORDER BY A.CREATED_DATE DESC LIMIT #{limit} OFFSET #{offset}

SELECT B.PRS_ID, B.PRS_NAME, B.PRS_COUNTRY,
-- 전체 노출 수 COUNT(*) AS TOTAL_CNT,
-- OS별 노출 수 (정산용) SUM(CASE WHEN A.OS = 'ANDROID' THEN 1 ELSE 0 END) AS ANDROID_CNT, SUM(CASE WHEN A.OS = 'IOS' THEN 1 ELSE 0 END) AS IOS_CNT
FROM WH_AD_LOG A JOIN WH_PRESS B ON A.PRS_ID = B.PRS_ID WHERE A.ACTION = 'IMPRESSION' AND DATE_FORMAT(A.CREATED_DATE, '%Y-%m') = #{targetMonth}
AND B.PRS_COUNTRY = #{country}
GROUP BY B.PRS_ID, B.PRS_NAME, B.PRS_COUNTRY ORDER BY TOTAL_CNT DESC

SELECT PRS_ID, PRS_NAME FROM WH_PRESS WHERE PRS_TYPE = '4' AND PRS_USE_YN = 'Y'
AND PRS_COUNTRY = #{country}
ORDER BY PRS_NAME ASC

mapper.update:
UPDATE ipo_requests 
SET status = #{status} 
WHERE id = #{id}

UPDATE WH_GUEST_COMMENT 
SET STATUS = #{STATUS} -- 'BLIND' 또는 'DELETE'
WHERE CMT_ID = #{cmtId}

mapper.insert:
INSERT INTO WH_GUEST_REPORT (
    TARGET_TYPE, TARGET_ID, REPORTER_DEVICE_ID, REASON, CREATED_DATE
) VALUES (
    'COMMENT', #{cmtId}, #{deviceId}, #{reason}, NOW()
)

INSERT INTO WH_GUEST_BLACKLIST (
    DEVICE_ID, REASON, PRS_ID, CREATED_DATE
) VALUES (
    #{targetDeviceId}, #{reason}, #{prsId}, NOW()
)
ON DUPLICATE KEY UPDATE REASON = #{reason}

INSERT INTO WH_GUEST_BLOCK (DEVICE_ID, REASON, CREATED_DATE)
VALUES (#{deviceId}, #{reason}, NOW())
ON DUPLICATE KEY UPDATE REASON = #{reason}

mapper.select:
SELECT COUNT(DISTINCT A.MEM_ID) FROM WH_AD_LOG A
INNER JOIN WH_PRESS B ON A.PRS_ID = B.PRS_ID AND B.PRS_COUNTRY = #{country}
WHERE A.ACTION = 'IMPRESSION' AND DATE(A.CREATED_DATE) = CURDATE()

SELECT IFNULL(ROUND((COUNT(DISTINCT TODAY.MEM_ID) / NULLIF(COUNT(DISTINCT YESTERDAY.MEM_ID), 0)) * 100), 0) FROM ( SELECT DISTINCT A.MEM_ID FROM WH_AD_LOG A
INNER JOIN WH_PRESS B ON A.PRS_ID = B.PRS_ID AND B.PRS_COUNTRY = #{country}
WHERE A.ACTION = 'IMPRESSION' AND DATE(A.CREATED_DATE) = DATE_SUB(CURDATE(), INTERVAL 1 DAY) ) YESTERDAY LEFT JOIN ( SELECT DISTINCT A.MEM_ID FROM WH_AD_LOG A
INNER JOIN WH_PRESS B ON A.PRS_ID = B.PRS_ID AND B.PRS_COUNTRY = #{country}
WHERE A.ACTION = 'IMPRESSION' AND DATE(A.CREATED_DATE) = CURDATE() ) TODAY ON YESTERDAY.MEM_ID = TODAY.MEM_ID

mapper.update:
UPDATE WH_VS_CARD
SET VISIBLE_YN = #{visibleYn}
WHERE VS_ID = #{vsId}
  AND USE_YN = 'Y'

UPDATE WH_VS_CARD
SET IS_PINNED = #{isPinned}
WHERE VS_ID = #{vsId}
  AND USE_YN = 'Y'

UPDATE WH_VS_CARD
SET PIN_ORDER = #{pinOrder}
WHERE VS_ID = #{vsId}
  AND USE_YN = 'Y'

mapper.select:
SELECT PRS_ID, PRS_NAME, PRS_COUNTRY, PRS_USE_YN, IFNULL(STAR_CATEGORY, 'GENERAL') AS STAR_CATEGORY, IFNULL(FOLLOWER_CNT, 0) AS FOLLOWER_CNT, (SELECT COUNT(*) FROM WH_AD_LOG WHERE PRS_ID = A.PRS_ID AND ACTION = 'IMPRESSION') AS AD_VIEW_CNT FROM WH_PRESS A WHERE PRS_TYPE = '4' AND PRS_AUTH = 'ST'
AND PRS_COUNTRY = #{country}
AND (PRS_NAME LIKE CONCAT('%', #{searchKeyword}, '%') OR PRS_ID LIKE CONCAT('%', #{searchKeyword}, '%'))
AND IFNULL(STAR_CATEGORY, 'GENERAL') = #{filterCategory}
ORDER BY (IFNULL(STAR_CATEGORY, 'GENERAL') = 'GENERAL') DESC, FOLLOWER_CNT DESC, PRS_CREATE_DATE DESC
LIMIT #{start}, #{length}

SELECT COUNT(*)
FROM WH_PRESS A
WHERE PRS_TYPE = '4' AND PRS_AUTH = 'ST'

    AND PRS_COUNTRY = #{country}


    AND (PRS_NAME LIKE CONCAT('%', #{searchKeyword}, '%') OR PRS_ID LIKE CONCAT('%', #{searchKeyword}, '%'))


    AND IFNULL(STAR_CATEGORY, 'GENERAL') = #{filterCategory}

mapper.update:
UPDATE WH_PRESS
SET STAR_CATEGORY = #{category},
    PRS_UPDATE_DATE = CURRENT_TIMESTAMP
WHERE PRS_ID = #{prsId}
  AND PRS_TYPE = '4' AND PRS_AUTH = 'ST'

  AND PRS_COUNTRY = #{country}

mapper.select:
SELECT * FROM ( SELECT 'MEMBER_CONTENT' AS TARGET_TYPE, CAST(C.CON_ID AS CHAR) AS TARGET_ID, C.CON_TITLE AS TITLE, C.CON_BODY AS BODY, C.CON_THUMNAIL AS IMAGE_URL, C.MDR_STATUS, DATE_FORMAT(C.CON_CREATE_DATE, '%Y-%m-%d %H:%i') AS CREATED_TEXT, C.CON_CREATE_DATE AS CREATED_DATE, -- 작성자는 ID로만 표시한다. 이름을 붙이려고 WH_MEMBER를 조인했다가 -- 운영 DB에 그 테이블이 없어 화면 전체가 500으로 떨어졌다. C.PRS_ID AS WRITER FROM WH_CONTENT C WHERE C.MDR_STATUS = #{status}
UNION ALL
SELECT 'STAR_FEED' AS TARGET_TYPE, CAST(S.CON_ID AS CHAR) AS TARGET_ID, NULL AS TITLE, S.CON_BODY AS BODY, D.MEDIA_URL AS IMAGE_URL, S.MDR_STATUS, DATE_FORMAT(S.CREATED_DATE, '%Y-%m-%d %H:%i') AS CREATED_TEXT, S.CREATED_DATE, IFNULL(P.PRS_NAME, S.PRS_ID) AS WRITER FROM WH_STAR_CONTENT S LEFT JOIN STAR_CONTENT_MEDIA D ON S.CON_ID = D.CON_ID AND D.SORT_ORDER = 0 LEFT JOIN WH_PRESS P ON S.PRS_ID = P.PRS_ID WHERE S.MDR_STATUS = #{status} AND D.MEDIA_TYPE = 'PHOTO' ) Q ORDER BY Q.CREATED_DATE ASC LIMIT 200

choose.otherwise:
SELECT C.CON_ID, C.MDR_STATUS, C.CON_THUMNAIL AS IMAGE_URL
FROM WH_CONTENT C
WHERE C.CON_ID = #{targetId}

choose.when:
UPDATE WH_STAR_CONTENT
SET MDR_STATUS = #{status}, MDR_DATE = NOW(), MDR_ADMIN = #{adminId}
WHERE CON_ID = #{targetId} AND MDR_STATUS = #{fromStatus}

choose.otherwise:
UPDATE WH_CONTENT
SET MDR_STATUS = #{status}, MDR_DATE = NOW(), MDR_ADMIN = #{adminId}
WHERE CON_ID = #{targetId} AND MDR_STATUS = #{fromStatus}
